// Log-mel spectrogram preprocessing matching NeMo's AudioToMelSpectrogramPreprocessor.
// Mirrors mlx_audio/stt/models/nemotron_asr/audio.py.
//
// 128 slaney mels, preemphasis 0.97, symmetric hann window center-padded to n_fft,
// power spectrogram, log with additive guard, no normalization (`normalize: NA`),
// no dither at inference. The slaney filterbank is a BAKED resource (see
// Resources/mel_filters_slaney_128.safetensors, generated by PORTING/oracle).

import Foundation
import MLX
import MLXAudioDSP
import MLXFFT

public enum NemotronAudio {

    /// Symmetric hann window of `winLength`, center-padded to `nFFT`
    /// (matches torch.stft / NeMo).
    static func paddedWindow(_ args: PreprocessArgs) -> MLXArray {
        var window = AudioDSP.hannWindow(args.winLength, periodic: false)
        if window.dim(0) < args.nFFT {
            let left = (args.nFFT - window.dim(0)) / 2
            let right = args.nFFT - window.dim(0) - left
            window = concatenated([
                MLXArray.zeros([left], dtype: window.dtype),
                window,
                MLXArray.zeros([right], dtype: window.dtype),
            ])
        }
        return window
    }

    /// Signal-level pre-emphasis: y[0] = x[0]; y[n] = x[n] − c·x[n−1].
    /// (Distinct from AudioDSP.preEmphasized, which is kaldi per-frame.)
    static func preemphasized(_ x: MLXArray, _ args: PreprocessArgs) -> MLXArray {
        guard args.preemph > 0 else { return x }
        let n = x.dim(0)
        return concatenated([x[0 ..< 1], x[1 ..< n] - args.preemph * x[0 ..< (n - 1)]], axis: 0)
    }

    /// The baked (nMels, nFFT/2+1) slaney filterbank resource.
    static let melFilters: MLXArray = {
        guard
            let url = Bundle.module.url(
                forResource: "mel_filters_slaney_128", withExtension: "safetensors")
        else { fatalError("missing baked mel filterbank resource") }
        guard let filters = try? MLX.loadArrays(url: url)["mel_filters"] else {
            fatalError("malformed mel filterbank resource")
        }
        return filters
    }()

    /// power (t, nBins) → log-mel (1, t, nMels).
    static func powerToLogMel(
        _ power: MLXArray, _ args: PreprocessArgs, dtype: DType
    ) -> MLXArray {
        var x = AudioDSP.applyMelFilterbank(power, filters: melFilters.asType(power.dtype))
        x = log(x + MLXArray(args.logZeroGuardValue).asType(x.dtype))
        // normalize "NA" is a no-op — the only mode this model was trained with.
        precondition(
            args.normalize != "per_feature" && args.normalize != "all_features",
            "normalize=\(args.normalize) not supported (model uses NA)")
        return expandedDimensions(x, axis: 0).asType(dtype)
    }

    /// (1, T, features) log-mel features for a mono waveform (samples,).
    public static func logMelSpectrogram(_ x: MLXArray, _ args: PreprocessArgs) -> MLXArray {
        let originalDtype = x.dtype
        var x = x

        if args.padTo > 0 && x.dim(0) < args.padTo {
            x = padded(x, widths: [IntOrPair((0, args.padTo - x.dim(0)))])
        }

        let window = paddedWindow(args)
        x = preemphasized(x, args)

        // center=True, pad_mode="constant"
        x = padded(x, widths: [IntOrPair((args.nFFT / 2, args.nFFT / 2))])
        let frames = AudioDSP.framed(x, frameLength: args.nFFT, hop: args.hopLength)
        let power = AudioDSP.powerSpectrum(frames, window: window).asType(originalDtype)

        return powerToLogMel(power, args, dtype: originalDtype)
    }

    /// A contiguous full-audio-equivalent log-mel frame range [frameStart, frameEnd).
    /// Preserves the same frame centers, center padding, and preemphasis state as the
    /// full pass without materializing the full STFT (long-audio OOM fix, upstream #817).
    public static func logMelSpectrogramFrames(
        _ x: MLXArray, _ args: PreprocessArgs, frameStart: Int, frameEnd: Int
    ) -> MLXArray {
        var x = x
        if args.padTo > 0 && x.dim(0) < args.padTo {
            x = padded(x, widths: [IntOrPair((0, args.padTo - x.dim(0)))])
        }
        return logMelFrames(
            buffer: x, bufferStart: 0, totalSamples: x.dim(0), args,
            frameStart: frameStart, frameEnd: frameEnd)
    }

    /// Shared frame math for the whole-buffer path above and `NemotronStreamingSession`,
    /// which only holds a trailing window of an arriving stream.
    ///
    /// `buffer` carries the samples starting at global index `bufferStart`, and must span
    /// `[frameStart·hop − nFFT/2 − 1, min(sampleEnd, totalSamples))` — the extra leading
    /// sample is the pre-emphasis look-back. Pass the global sample count as `totalSamples`
    /// once the stream has ended, so the tail frames get the same right zero-padding a full
    /// pass would apply; pass `nil` mid-stream, where the caller only asks for frames whose
    /// windows have fully arrived.
    static func logMelFrames(
        buffer: MLXArray, bufferStart: Int, totalSamples: Int?, _ args: PreprocessArgs,
        frameStart: Int, frameEnd: Int
    ) -> MLXArray {
        let originalDtype = buffer.dtype

        if frameEnd <= frameStart {
            return MLXArray.zeros([1, 0, args.features], dtype: originalDtype)
        }

        let hop = args.hopLength
        let nFFT = args.nFFT
        let numFrames = frameEnd - frameStart
        let sampleStart = frameStart * hop - nFFT / 2
        let sampleEnd = (frameEnd - 1) * hop - nFFT / 2 + nFFT
        let bufferEnd = bufferStart + buffer.dim(0)
        let limit = totalSamples ?? bufferEnd

        let rawStart = max(sampleStart, 0)
        let rawEnd = min(sampleEnd, limit)
        precondition(
            rawStart >= bufferStart && rawEnd <= bufferEnd,
            "frames [\(frameStart), \(frameEnd)) need samples [\(rawStart), \(rawEnd)), "
                + "outside the buffered window [\(bufferStart), \(bufferEnd))")
        var raw = buffer[(rawStart - bufferStart) ..< (rawEnd - bufferStart)]

        // Preemphasis with the same previous-sample state as a full-utterance pass.
        if args.preemph > 0 && raw.dim(0) > 0 {
            if rawStart > 0 {
                precondition(
                    rawStart - 1 >= bufferStart,
                    "pre-emphasis look-back sample \(rawStart - 1) is no longer buffered")
                let prev = buffer[(rawStart - 1 - bufferStart) ..< (rawStart - bufferStart)]
                let first = raw[0 ..< 1] - args.preemph * prev
                let n = raw.dim(0)
                raw = concatenated([first, raw[1 ..< n] - args.preemph * raw[0 ..< (n - 1)]], axis: 0)
            } else {
                raw = preemphasized(raw, args)
            }
        }

        let leftPad = max(-sampleStart, 0)
        let rightPad = max(sampleEnd - limit, 0)
        var pieces: [MLXArray] = []
        if leftPad > 0 { pieces.append(MLXArray.zeros([leftPad], dtype: originalDtype)) }
        pieces.append(raw.asType(originalDtype))
        if rightPad > 0 { pieces.append(MLXArray.zeros([rightPad], dtype: originalDtype)) }
        var segment = pieces.count > 1 ? concatenated(pieces, axis: 0) : pieces[0]

        let expectedLen = (numFrames - 1) * hop + nFFT
        if segment.dim(0) < expectedLen {
            segment = padded(segment, widths: [IntOrPair((0, expectedLen - segment.dim(0)))])
        }

        let window = paddedWindow(args)
        let frames = asStrided(segment, [numFrames, nFFT], strides: [hop, 1])
        let power = AudioDSP.powerSpectrum(frames, window: window).asType(originalDtype)
        return powerToLogMel(power, args, dtype: originalDtype)
    }

    /// Iterate full-audio-equivalent log-mel chunks with bounded STFT memory.
    public static func iterLogMelSpectrogram(
        _ x: MLXArray, _ args: PreprocessArgs, chunkFrames: Int,
        _ body: (MLXArray) throws -> Void
    ) rethrows {
        precondition(chunkFrames > 0, "chunkFrames must be positive")
        var totalSamples = x.dim(0)
        if args.padTo > 0 && totalSamples < args.padTo { totalSamples = args.padTo }

        let totalFrames = totalSamples / args.hopLength + 1
        var frameStart = 0
        while frameStart < totalFrames {
            let frameEnd = min(frameStart + chunkFrames, totalFrames)
            try body(logMelSpectrogramFrames(x, args, frameStart: frameStart, frameEnd: frameEnd))
            frameStart += chunkFrames
        }
    }
}
